type DNSCache struct {
	mu   sync.RWMutex
	data map[string][]net.IP
}

// NewDNSCache creates a new instance of the cache
func NewDNSCache() *DNSCache {
	return &DNSCache{
		data: make(map[string][]net.IP),
	}
}

// Get retrieves the IP addresses for a hostname from the cache.
// It returns nil if the hostname is not found.
func (c *DNSCache) Get(hostname string) []net.IP {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.data[hostname]
}

// Set stores the IP addresses for a hostname in the cache.
func (c *DNSCache) Set(hostname string, ips []net.IP) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.data[hostname] = ips
