```javascript
import { Worker } from '@ember/worker';

// We define the worker logic here. 
// In a real app, you might want to separate this into a .ts file or a separate package.
export default class CsvWorker extends Worker {
  constructor() {
    super();
    this.onmessage = (event) => {
      const { fileContent, delimiter } = event.data;

      try {
        const rows = this.parseCSV(fileContent, delimiter);
        this.postMessage({
          type: 'success',
          data: rows
        });
      } catch (error) {
        this.postMessage({
          type: 'error',
          message: error.message
        });
      }
    };
  }

  parseCSV(content, delimiter = ',') {
    const lines = content.split(/\r\n|\n/);
    const headers = lines[0].split(delimiter).map(h => h.trim());
    const data = [];

    for (let i = 1; i < lines.length; i++) {
      if (!lines[i].trim()) continue; // Skip empty lines

      const values = lines[i].split(delimiter).map(v => v.trim());

      // Basic validation to ensure row length matches headers
      if (values.length === headers.length) {
        data.push({
          [headers[0]]: values[0],
          [headers[1]]: values[1],
          // ... map all headers
        });
      }
    }
    return data;
  }
}
```

