```

### 3. The SQL Reader Service (`src/main/java/com/example/app/SqlReader.java`)

This class handles reading the file content.

```java
package com.example.app.service;

import org.springframework.stereotype.Service;
import org.springframework.core.io.ClassPathResource;
import org.springframework.core.io.Resource;
import org.springframework.core.io.support.PathMatchingResourcePatternResolver;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

@Service
public class SqlReader {

    private final PathMatchingResourcePatternResolver resolver = new PathMatchingResourcePatternResolver();

    public String readQuery() throws IOException {
        // Try to read from classpath first (src/main/resources)
        Resource resource = resolver.getResource("classpath:query.sql");
        if (resource.exists()) {
            return resource.getInputStream().readAllBytes();
        }

        // Fallback to file system if not in classpath
        Path path = Paths.get("query.sql");
        if (Files.exists(path)) {
            return Files.readString(path);
        }

        throw new IOException("SQL file not found");
    }
}
```

